// Log for debugging
console.log("rawMessage:", rawMessage);

if (!rawMessage) {
  // If no message, return empty
  return [];
}

// Parse the JSON string into an object
let mqttMessage;
try {
  mqttMessage = JSON.parse(rawMessage);
} catch (error) {
  console.error("Failed to parse MQTT message:", error);
  return [];
}

// Retrieve sensor values
const sensors = mqttMessage.sensors;
const units = mqttMessage.units;
const topic = $input.first().json.topic;

// Format the text for the LLM
const formattedText = `
Received data from topic "${topic}":
- Temperature: ${sensors.temperature} ${units.temperature}
- Humidity: ${sensors.humidity} ${units.humidity}
- Light: ${sensors.light} ${units.light}
Timestamp: ${mqttMessage.timestamp}

Please analyze this data and provide insights or alerts if necessary.
`;

return [
  {
    json: {
      text: formattedText
    }
  }
];

